from pathlib import Path
import json,subprocess,datetime,time,os,hashlib,re
O=Path(__file__).parent;pin=json.loads((O/'PIN.json').read_text());W=Path(pin['source_worktree']);S=Path(os.environ['TCSLIB_SCRATCH']);rows=json.loads((O/'GUARD-INPUTS.json').read_text());out=O/'guard-runs';out.mkdir(exist_ok=True);results=[]
for d in rows:
 label=str(d['id'])+'-'+d['name'].replace('.','_');file=Path(d['input']);assert hashlib.sha256(file.read_bytes()).hexdigest()==d['input_sha256'];assert not (out/(label+'.json')).exists();argv=['bash',str(W/'devtools/seyoon/leanelab.sh'),d['project'],str(S/'oleans-mac8'),d['path']];start=datetime.datetime.now(datetime.timezone.utc).isoformat();tm=time.monotonic();r=subprocess.run(argv,cwd=d['project'],stdout=subprocess.PIPE,stderr=subprocess.STDOUT);raw=r.stdout;(out/(label+'.out')).write_bytes(raw);text=raw.decode(errors='replace');errors=[{'line':int(m.group(1)),'column':int(m.group(2)),'message':m.group(3)} for m in re.finditer(r'\.lean:(\d+):(\d+): error(?:\([^\n]*?\))?:([^\n]*)',text)];checks=[l.split('GUARD_OK|',1)[1] for l in text.splitlines() if 'GUARD_OK|' in l];guardok=len(checks)==1 and checks[0].split('|',1)[0]==str(d['id']);states=json.loads(checks[0].split('|',1)[1]) if guardok else [];assert not guardok or {q['name'] for q in states}==set(d['ordinary_heads']);result=d|{'actual_execution':True,'argv':argv,'start_utc':start,'seconds':time.monotonic()-tm,'exit':r.returncode,'errors':len(errors),'error_lines':errors,'declaration_sorry_warnings':raw.count(b"declaration uses 'sorry'"),'output_bytes':len(raw),'output_sha256':hashlib.sha256(raw).hexdigest(),'output_file':'guard-runs/'+label+'.out','guard_status_witness':guardok,'guard_states':states,'PASS_compilation':r.returncode==0 and len(errors)==0 and guardok,'full_foreign_head_scope_but_static_explicit_argument_review_still_required':True};(out/(label+'.json')).write_text(json.dumps(result,indent=2)+'\n');results.append(result);(O/'GUARD-RESULTS.json').write_text(json.dumps(results,indent=2)+'\n');print(json.dumps({k:result[k] for k in ['id','name','ordinary_head_count','seconds','exit','errors','guard_status_witness','PASS_compilation']}),flush=True)
